<?php
require dirname(__DIR__).'/app/bootstrap.php';
function admin_user(){return $_SESSION['admin']??null;} function require_admin(){if(!admin_user()){header('Location: /admin/');exit;}}
$action=$_GET['action']??'dashboard';$message=''; if($action==='logout'){session_destroy();header('Location: /admin/');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if($action==='login'){$q=db()->prepare('SELECT id,name,username,password_hash,role FROM users WHERE username=? LIMIT 1');$q->execute([trim($_POST['username'])]);$u=$q->fetch();if($u&&password_verify($_POST['password'],$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['admin']=$u;header('Location: /admin/');exit;}$message='Invalid username or password.';}elseif($action==='save'){require_admin();try{$type=$_POST['type']??'post';$id=(int)($_POST['id']??0);$slug=preg_replace('/[^a-z0-9]+/','-',strtolower(trim($_POST['slug']?:$_POST['title'])));$image=trim($_POST['image_path']??'');if(!empty($_FILES['image']['name'])){$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);if(!isset($allowed[$mime])||$_FILES['image']['size']>5*1024*1024)throw new RuntimeException('Upload JPG, PNG, or WebP under 5 MB.');$file=bin2hex(random_bytes(16)).'.'.$allowed[$mime];$dir=ROOT_PATH.'/storage/uploads';if(!is_dir($dir))mkdir($dir,0755,true);move_uploaded_file($_FILES['image']['tmp_name'],$dir.'/'.$file);$image='/storage/uploads/'.$file;}$data=[trim($_POST['title']),$slug,trim($_POST['excerpt']),$_POST['body']??'',$image,$_POST['status']??'draft',trim($_POST['meta_title']),trim($_POST['meta_description'])];if($id){$q=db()->prepare('UPDATE content SET title=?,slug=?,excerpt=?,body=?,image_path=?,status=?,meta_title=?,meta_description=?,published_at=IF(?="published",NOW(),published_at) WHERE id=?');$q->execute([...$data,$data[5],$id]);}else{$q=db()->prepare('INSERT INTO content(type,title,slug,excerpt,body,image_path,status,meta_title,meta_description,published_at) VALUES(?,?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))');$q->execute([$type,...$data,$data[5]]);}$message='Content saved.';$action='content';}catch(Throwable $e){$message='Could not save: '.$e->getMessage();}}}
if(!admin_user()):?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login | Ellens Florist</title><link rel="stylesheet" href="/assets/css/main.css"></head><body><main class="section tinted" style="min-height:100vh;display:grid;place-items:center"><form class="form-wrap" method="post" style="width:min(440px,100%)"><p class="eyebrow">Ellens Florist</p><h1 style="font-size:2.5rem">Admin login</h1><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input required name="username"></p><p><label>Password</label><input required type="password" name="password"></p><button class="button gold">Sign in</button></form></main></body></html><?php exit;endif;
$content=[];if(in_array($action,['content','edit'],true))$content=db()->query('SELECT * FROM content ORDER BY updated_at DESC')->fetchAll();$edit=null;if($action==='edit'&&isset($_GET['id'])){$q=db()->prepare('SELECT * FROM content WHERE id=?');$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | Ellens Florist</title><link rel="stylesheet" href="/assets/css/main.css"><style>.admin{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.admin aside{background:#2b2b2b;color:#faf8f5;padding:25px}.admin aside a{display:block;padding:9px 0}.admin main{padding:clamp(25px,5vw,60px)}table{width:100%;border-collapse:collapse;background:#fff}th,td{text-align:left;padding:12px;border-bottom:1px solid #eee}@media(max-width:700px){.admin{grid-template-columns:1fr}.admin aside{display:flex;gap:15px;flex-wrap:wrap}.admin aside a{padding:0}}</style></head><body><div class="admin"><aside><b>Ellens Florist</b><small style="display:block">Admin panel</small><hr><a href="/admin/">Dashboard</a><a href="/admin/?action=content">Content library</a><a href="/admin/?action=edit">Add content</a><a href="/admin/?action=inquiries">Wedding inquiries</a><a href="/admin/?action=messages">Contact messages</a><a href="/admin/?action=logout">Log out</a></aside><main><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif?><?php if($action==='dashboard'):?><p class="eyebrow">Welcome, <?=e(admin_user()['name'])?></p><h1 style="font-size:3rem">Dashboard</h1><p>Use the Content library to edit temporary gallery photos, testimonials, journal articles, and packages.</p><?php elseif($action==='content'):?><h1 style="font-size:3rem">Content library</h1><p><a class="button gold" href="?action=edit">Add content</a></p><table><tr><th>Title</th><th>Type</th><th>Status</th><th></th></tr><?php foreach($content as $row):?><tr><td><?=e($row['title'])?></td><td><?=e($row['type'])?></td><td><?=e($row['status'])?></td><td><a href="?action=edit&id=<?=$row['id']?>">Edit</a></td></tr><?php endforeach?></table><?php elseif($action==='edit'):$edit=$edit?:['id'=>'','type'=>'post','title'=>'','slug'=>'','excerpt'=>'','body'=>'','image_path'=>'','status'=>'draft','meta_title'=>'','meta_description'=>''];?><h1 style="font-size:3rem"><?=$edit['id']?'Edit':'Add'?> content</h1><form method="post" enctype="multipart/form-data" class="form-wrap"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><div class="form-grid"><p><label>Content type</label><select name="type"><?php foreach(['post','gallery','testimonial','package','faq']as$t):?><option <?=$edit['type']===$t?'selected':''?>><?=$t?></option><?php endforeach?></select></p><p><label>Status</label><select name="status"><option <?=$edit['status']==='draft'?'selected':''?>>draft</option><option <?=$edit['status']==='published'?'selected':''?>>published</option></select></p><p class="full"><label>Title</label><input required name="title" value="<?=e($edit['title'])?>"></p><p class="full"><label>Slug</label><input name="slug" value="<?=e($edit['slug'])?>"></p><p class="full"><label>Short text / review</label><textarea name="excerpt"><?=e($edit['excerpt'])?></textarea></p><p class="full"><label>Photo upload</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small class="help">JPG, PNG, or WebP under 5 MB. Current: <?=e($edit['image_path'])?></small></p><p class="full"><label>Existing photo path (optional)</label><input name="image_path" value="<?=e($edit['image_path'])?>"></p><p class="full"><label>Full content (HTML supported)</label><textarea name="body" style="min-height:220px"><?=e($edit['body'])?></textarea></p><p><label>SEO title</label><input name="meta_title" value="<?=e($edit['meta_title'])?>"></p><p><label>SEO description</label><input name="meta_description" value="<?=e($edit['meta_description'])?>"></p><p class="full"><button class="button gold">Save content</button></p></div></form><?php else:$table=$action==='inquiries'?'inquiries':'contact_messages';$rows=db()->query("SELECT * FROM $table ORDER BY created_at DESC LIMIT 100")->fetchAll();?><h1 style="font-size:3rem"><?=e(ucfirst(str_replace('_',' ',$table)))?></h1><table><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $head):?><th><?=e($head)?></th><?php endforeach?></tr><?php foreach($rows as $row):?><tr><?php foreach($row as $value):?><td><?=e((string)$value)?></td><?php endforeach?></tr><?php endforeach?><?php else:?><tr><td>No records yet.</td></tr><?php endif?></table><?php endif?></main></div></body></html>
